import os
from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first name in names that is a readable file inside NOTES_DIR.

    NOTES_DIR is resolved against the current working directory. Names are
    untrusted. A name is used only if it resolves (following symlinks) to a
    regular file located inside NOTES_DIR. Names that are empty, contain NUL
    bytes, are absolute, escape NOTES_DIR (for example via '..'), point outside
    it through a symlink, name a directory, are missing, or cannot be read are
    skipped. Returns "" when no name yields readable text.
    """
    base = Path(NOTES_DIR).resolve()
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            candidate = (base / name).resolve()
        except (OSError, RuntimeError, ValueError):
            continue
        if candidate == base or not candidate.is_relative_to(base):
            continue
        try:
            if not candidate.is_file():
                continue
            return candidate.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
    return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Change into a fresh temp dir containing notes/ and a secret outside it."""
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / NOTES_DIR
    notes.mkdir()
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    return notes


def test_returns_first_readable_in_order(workdir: Path) -> None:
    (workdir / "b.txt").write_text("B", encoding="utf-8")
    (workdir / "c.txt").write_text("C", encoding="utf-8")
    assert first_readable(["missing.txt", "b.txt", "c.txt"]) == "B"


def test_empty_names_returns_empty(workdir: Path) -> None:
    assert first_readable([]) == ""


def test_none_readable_returns_empty(workdir: Path) -> None:
    assert first_readable(["x.txt", "y.txt"]) == ""


def test_empty_name_is_skipped(workdir: Path) -> None:
    (workdir / "a.txt").write_text("A", encoding="utf-8")
    assert first_readable(["", "a.txt"]) == "A"


def test_nul_byte_name_is_skipped(workdir: Path) -> None:
    (workdir / "a.txt").write_text("A", encoding="utf-8")
    assert first_readable(["a.txt\x00.md", "a.txt"]) == "A"


def test_parent_traversal_cannot_read_outside(workdir: Path) -> None:
    (workdir / "a.txt").write_text("A", encoding="utf-8")
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["../secret.txt", "a.txt"]) == "A"


def test_traversal_back_into_notes_is_allowed_only_if_inside(workdir: Path) -> None:
    (workdir / "a.txt").write_text("A", encoding="utf-8")
    assert first_readable(["../notes/a.txt"]) == "A"


def test_absolute_path_outside_is_rejected(workdir: Path, tmp_path: Path) -> None:
    secret = tmp_path / "secret.txt"
    assert first_readable([str(secret)]) == ""


def test_symlink_pointing_outside_is_rejected(workdir: Path, tmp_path: Path) -> None:
    link = workdir / "link.txt"
    link.symlink_to(tmp_path / "secret.txt")
    (workdir / "a.txt").write_text("A", encoding="utf-8")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "a.txt"]) == "A"


def test_directory_name_is_skipped(workdir: Path) -> None:
    (workdir / "sub").mkdir()
    (workdir / "a.txt").write_text("A", encoding="utf-8")
    assert first_readable(["sub", "a.txt"]) == "A"


@pytest.mark.skipif(
    hasattr(os, "geteuid") and os.geteuid() == 0,
    reason="root can read mode-000 files",
)
def test_unreadable_file_is_skipped(workdir: Path) -> None:
    locked = workdir / "locked.txt"
    locked.write_text("L", encoding="utf-8")
    locked.chmod(0o000)
    (workdir / "a.txt").write_text("A", encoding="utf-8")
    try:
        assert first_readable(["locked.txt", "a.txt"]) == "A"
    finally:
        locked.chmod(0o644)
